import characters from "./characters_2.js";
import { base32ToUint8Array, decode, encode, uint8ArrayToBase32Array } from "./Base32.js";
import { primaryAlphabet } from "./characters.js";
export const hashToFingerprint = (hash) => {
    return uint8ArrayToBase32Array(hash);
};
export const fingerprintToHash = (fingerprint) => {
    return base32ToUint8Array(fingerprint);
};
export const publicKeyToPrimaryChars = (publicKey) => {
    return encode(uint8ArrayToBase32Array(publicKey), primaryAlphabet);
};
export const primaryCharsToUint8Array = (chars) => {
    return base32ToUint8Array(decode(chars, primaryAlphabet));
};
export const nameToPrimaryChars = (name) => {
    return Array.from(name)
        .map(char => characters.find(({ secondary }) => secondary.includes(char))?.primary ?? char)
        .join("");
};
